law_hereditary_bureaucrats:
NOR = {
	c:AUS ?= this # For the Austrian Empire and its subjects
	AND = {
		exists = c:AUS
		is_subject_of = c:AUS
	}

law_crownland_diets:
OR = {
	c:AUS ?= this # For the Austrian Empire and its subjects
	AND = {
		exists = c:AUS
		is_subject_of = c:AUS
	}

law_serfdom:
NOR = {
	c:AUS ?= this # Austria and the Danubian Principalities have manorialism instead
	AND = {
		exists = c:AUS
		is_subject_of = c:AUS
		OR = {
			is_subject_type = subject_type_crown_land
			is_subject_type = subject_type_personal_union
		}
		c:AUS ?= { has_law = law_type:law_manorialism }
	}
	country_has_primary_culture = cu:romanian

law_manorialism:
OR = {
	c:AUS ?= this # For the Austrian Empire and its subjects
	AND = {
		exists = c:AUS
		is_subject_of = c:AUS
		OR = {
			is_subject_type = subject_type_crown_land
			is_subject_type = subject_type_personal_union
		}
		c:AUS ?= { has_law = law_type:law_manorialism }
	}
	country_has_primary_culture = cu:romanian # Also for the Danubian principalities

